/* Expense Tracker service worker.
 * Strategy:
 *  - Precache the app shell + vendored ExcelJS from ./precache-manifest.json
 *    (generated by scripts/precache-manifest.mjs at build time).
 *  - Navigations: network-first, fall back to the cached shell (offline).
 *  - Same-origin assets: cache-first, lazily cached.
 *  - Cross-origin (Gemini / Drive / FX APIs): pass through, never cached
 *    (sensitive data + would break CORS/authorization semantics).
 * Receipt photos never go into Cache Storage (iOS caps it at ~50 MB); they live
 * in IndexedDB and Google Drive.
 */
// The COMMIT placeholder in the VERSION constant below is replaced at build
// time with the git SHA (see scripts/precache-manifest.mjs, which generates
// this file into dist/). A unique cache name per deploy forces the browser's
// update check to notice the new service worker, re-read the precache
// manifest, and
// swap in the new hashed assets — a byte-identical sw.js would never trigger
// a reinstall, and iOS standalone apps would keep serving the old cached
// shell indefinitely.
const VERSION = 'expense-tracker-v3-__COMMIT__';
const PRECACHE_URL = './precache-manifest.json';

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(VERSION);
      try {
        const res = await fetch(PRECACHE_URL, { cache: 'no-store' });
        if (res.ok) {
          const list = await res.json();
          await cache.addAll(list);
        }
      } catch (err) {
        // First-ever load while offline: nothing to precache yet.
      }
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // cross-origin: passthrough

  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(req);
          const cache = await caches.open(VERSION);
          await cache.put('./index.html', fresh.clone());
          return fresh;
        } catch (err) {
          const cached = await caches.match('./index.html');
          return cached || Response.error();
        }
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const cached = await caches.match(req);
      if (cached) return cached;
      const res = await fetch(req);
      if (res.ok) {
        const cache = await caches.open(VERSION);
        await cache.put(req, res.clone());
      }
      return res;
    })(),
  );
});
